(()=>{const URL='https://vnagbtgxxwgfdbpczlin.supabase.co',KEY='sb_publishable_eEIjtP8AI3-8USprPyncag_yhO545W4';let appLoaded=false;
const msg=t=>{const e=document.getElementById('loginMsg');if(e)e.innerHTML='<div class="error">'+String(t).replace(/[<>&]/g,'')+'</div>';};
const load=s=>new Promise((resolve,reject)=>{const x=document.createElement('script');x.src=s;x.onload=resolve;x.onerror=()=>reject(new Error('تعذر تحميل '+s));document.head.appendChild(x);});
async function ensureSupabase(){if(window.supabase)return;try{await load('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2');}catch(e){}if(!window.supabase)try{await load('https://unpkg.com/@supabase/supabase-js@2');}catch(e){}if(!window.supabase)throw new Error('تعذر تحميل مكتبة Supabase');}
async function loadApp(){if(appLoaded)return;await load('./app.js');appLoaded=true;}
window.login=async function(){const u=document.getElementById('username').value.trim(),p=document.getElementById('password').value;if(!u||!p){msg('أدخل اسم المستخدم وكلمة المرور.');return;}msg('جاري تسجيل الدخول...');try{const r=await fetch(URL+'/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json','apikey':KEY},body:JSON.stringify({email:u.toLowerCase()+'@icv-platform.local',password:p})});const d=await r.json();if(!r.ok){msg('فشل تسجيل الدخول: '+(d.error_description||d.msg||d.error||'بيانات الدخول غير صحيحة'));return;}await ensureSupabase();const client=window.__icvClient||(window.__icvClient=window.supabase.createClient(URL,KEY));const ss=await client.auth.setSession({access_token:d.access_token,refresh_token:d.refresh_token});if(ss.error)throw ss.error;const gs=await client.auth.getSession();if(!gs.data?.session)throw new Error('تم التحقق من كلمة المرور لكن لم يتم تثبيت جلسة الدخول.');await loadApp();if(typeof window.load==='function')await window.load(d.user);else{document.getElementById('loginPage').classList.add('hidden');document.getElementById('app').classList.remove('hidden');} }catch(e){msg('خطأ أثناء تسجيل الدخول: '+(e.message||e));}};
window.addEventListener('error',e=>{if(e.message)msg('خطأ في تشغيل المنصة: '+e.message);});
})();